// hide only after the predicate stays false for [_jumpGlyphHideDebounce].
// Never show the action when no track is playing.
bool resolveJumpGlyphVisible({
  required bool hasTrack,
  required bool needsJump,
}) {
  if (!hasTrack) {
    jumpGlyphHideTimer.value?.cancel();
    jumpGlyphHideTimer.value = null;
    jumpGlyphLatched.value = false;
    return false;
