  jumpGlyphHideTimer.value ??= Timer(_jumpGlyphHideDebounce, () {
    jumpGlyphHideTimer.value = null;
    if (isMounted()) {
      jumpGlyphLatched.value = false;
      rebuildTick.value++; // force the one rebuild that drops the glyph
    }
  });
  return true;
}

